"""Normalize complete original16px room objects with uniform integer sampling."""
import argparse,json,math
from pathlib import Path
from PIL import Image
import catalog
ROOT=Path(__file__).resolve().parents[1]
PROMPTS={
'computer':'One complete tiny desk computer sprite for a Pokémon Emerald / FireRed style GBA top-down RPG room, intended logical size EXACTLY16x16 pixels shown enlarged with hard square pixel clusters. A squat gray CRT monitor with a complete dark screen, pale cyan screen reflection, thick charcoal and pale gray bezel, and a small complete light-gray keyboard directly in front of it. Slight top-down three-quarter front view, monitor above keyboard, every part contained in16 by16 logical pixels. Very compact ordinary computer terminal, not a standing tall PC and no tower. Restrained10-color native GBA palette, crisp stepped edges, no gradients, no text or numbers. Truly transparent background outside the complete monitor AND keyboard, no desk surface, no floor, no wall, no grid, no labels.',
'flowerpot':'One complete tiny house flower planter sprite in the pixel-art style of Pokémon Emerald / FireRed, intended logical resolution EXACTLY16 pixels wide by16 pixels tall, shown enlarged as clean hard square pixel clusters. A compact rectangular warm-brown wooden planter box filling the bottom4 logical pixels; a little green foliage and two cheerful small yellow-orange blossoms above it, with short stems. Front/three-quarter top-down GBA JRPG room-object perspective. Complete flower heads AND complete planter base all fit inside a single16x16 game tile. Bright but restrained12-color native GameBoyAdvance palette. Large pixel clusters, crisp stepped outlines. No dangling or hanging flowers, no long vase or long stalks, no stand, no glow or gradients, no text, no grid, no floor or wall. Genuinely transparent background outside the single complete planted flower box.'}
def main():
 p=argparse.ArgumentParser();p.add_argument('kind',choices=PROMPTS);p.add_argument('source',type=Path);a=p.parse_args();im=Image.open(a.source).convert('RGBA');im.putalpha(im.getchannel('A').point(lambda v:255 if v>=128 else 0));b=im.getbbox();f=math.ceil(max(b[2]-b[0],b[3]-b[1])/16);cx=(b[0]+b[2])//2;box=(cx-8*f,b[3]-16*f,cx+8*f,b[3]);assert box[0]<=b[0]and box[1]<=b[1]and box[2]>=b[2];tile=im.crop(box).resize((16,16),Image.Resampling.NEAREST).quantize(colors=16,method=Image.Quantize.FASTOCTREE,dither=Image.Dither.NONE).convert('RGBA');tile.putalpha(tile.getchannel('A').point(lambda v:255 if v>=128 else 0));folder=ROOT/'assets/original'/('interior-'+a.kind);folder.mkdir(exist_ok=True,parents=True);path=folder/(a.kind+'.png');tile.save(path);proof={'origin':'Original complete compact Gen3 room '+a.kind,'tool':'image_gen.imagegen','prompt':PROMPTS[a.kind],'source_file':a.source.name,'source_sha256':catalog.sha(a.source.read_bytes()),'source_size':im.size,'visible_bounds':b,'crop':box,'integer_reduction':f,'final_size':[16,16],'binary_alpha':128,'palette_colors':16,'dither':False,'whole_object_preserved':True,'files':{path.name:catalog.sha(path.read_bytes())}};(folder/'provenance.json').write_text(json.dumps(proof,indent=2)+'\n');print(json.dumps(proof))
if __name__=='__main__':main()
